import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"インスタントアンサーとキーワードショートカット","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/instant-answers.md","filePath":"ja-JP/user-guide/instant-answers.md","lastUpdated":1786117994000}'),d={name:"ja-JP/user-guide/instant-answers.md"};function r(n,e,c,i,l,h){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="インスタントアンサーとキーワードショートカット" tabindex="-1">インスタントアンサーとキーワードショートカット <a class="header-anchor" href="#インスタントアンサーとキーワードショートカット" aria-label="Permalink to &quot;インスタントアンサーとキーワードショートカット&quot;">​</a></h1><p>一部の検索結果は、ファイル検索を待つことなく、入力した瞬間に表示されます。これは常に有効なものと、実際のクエリの前に短いキーワードを入力することで有効になるものがあります (こうすることで、ブラウザ履歴検索のような大きな機能が、無関係なキー入力のたびに注目を奪い合うことを防いでいます)。キーワードで起動するもののほとんどは、<strong>設定 → プラグイン → 設定</strong> でそのキーワードを設定できます。</p><h2 id="常時有効" tabindex="-1">常時有効 <a class="header-anchor" href="#常時有効" aria-label="Permalink to &quot;常時有効&quot;">​</a></h2><p>これらはキーワード不要で、入力した内容がパターンに一致した時点で有効になります。</p><h3 id="電卓" tabindex="-1">電卓 <a class="header-anchor" href="#電卓" aria-label="Permalink to &quot;電卓&quot;">​</a></h3><p>数式を直接入力すると、結果がリアルタイムに表示され、<strong>Enter</strong> でクリップボードにコピーされます:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>12 * (4 + 3)</span></span></code></pre></div><p>明示的な基数変換にも対応しています:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>255 to hex</span></span>
<span class="line"><span>0xFF to dec</span></span></code></pre></div><h3 id="環境変数" tabindex="-1">環境変数 <a class="header-anchor" href="#環境変数" aria-label="Permalink to &quot;環境変数&quot;">​</a></h3><ul><li><code>%NAME%</code> は特定の変数を展開します (<code>%PATH%</code> のような複数パスを含む変数は、パスごとに 1 エントリに分割されます)。</li><li><code>%partial</code> は、名前が <code>partial</code> に一致するすべての変数をあいまい検索で一覧表示します。</li></ul><h3 id="コマンドを実行する" tabindex="-1">コマンドを実行する <a class="header-anchor" href="#コマンドを実行する" aria-label="Permalink to &quot;コマンドを実行する&quot;">​</a></h3><ul><li><code>#&lt;command&gt;</code> はコマンドプロンプトウィンドウを開き、<code>&lt;command&gt;</code> を <strong>管理者として</strong> 実行します。</li><li><code>$&lt;command&gt;</code> はコマンドプロンプトウィンドウを開き、<code>&lt;command&gt;</code> を通常どおり実行します。</li></ul><h3 id="裸の-url" tabindex="-1">裸の URL <a class="header-anchor" href="#裸の-url" aria-label="Permalink to &quot;裸の URL&quot;">​</a></h3><p><code>http://</code>/<code>https://</code> から始まるアドレスを入力または貼り付けると、Lertaro がそれを直接開くことを提案します。</p><h2 id="キーワードで起動-組み込み、プレフィックスは設定可能" tabindex="-1">キーワードで起動 (組み込み、プレフィックスは設定可能) <a class="header-anchor" href="#キーワードで起動-組み込み、プレフィックスは設定可能" aria-label="Permalink to &quot;キーワードで起動 (組み込み、プレフィックスは設定可能)&quot;">​</a></h2><p>キーワードを入力し、スペースを挟んでからクエリを入力します。各キーワードには既定の短いプレフィックスが設定されていますが、よく入力する他の何かと衝突する場合は、そのプラグイン独自の <strong>設定</strong> ダイアログで個別に変更できます。</p><table tabindex="0"><thead><tr><th>キーワード (既定)</th><th>プラグイン</th><th>検索対象</th></tr></thead><tbody><tr><td><code>ps</code></td><td>プロセスマネージャー</td><td>名前、PID、またはウィンドウタイトルによる実行中のプロセス (あいまい検索/ピンイン一致にも対応) — 選択すると終了できます。</td></tr><tr><td><code>win</code></td><td>ウィンドウ切り替え</td><td>現在開いている、切り替え可能なウィンドウ (Alt+Tab で表示されるものと同じ集合) をタイトル、プロセス名、または PID で検索。選択すると前面に表示されます。</td></tr><tr><td><code>bm</code></td><td>ブラウザデータ</td><td>そのプラグイン自身の設定に追加した Chrome/Chromium 系および Firefox 系ブラウザのプロファイルから、ブックマークと履歴を検索します。</td></tr><tr><td><code>set</code></td><td>コア拡張機能</td><td>アプリ内のすべての設定を名前であいまい検索 — 選択すると、設定画面内の該当項目にハイライト付きで直接ジャンプします。<code>set</code> の後に何も入力しなければ、すべての設定を一覧表示します。</td></tr></tbody></table><p>ウィンドウ切り替えは既定で、各ウィンドウの実際の内容のライブサムネイルをアイコンとして表示します。これはバックグラウンドでキャプチャされるため、入力の速度が遅くなることはありません — まず通常のアプリアイコンが即座に表示され、サムネイルの準備ができ次第フェードインします。<strong>設定 → プラグイン → ウィンドウ切り替え → 設定</strong> で <strong>ウィンドウの内容をアイコンとして表示</strong> をオフにすると、このキャプチャを完全にスキップし、常にアプリアイコンを使用します。真の排他的フルスクリーンで動作しているウィンドウ (ほとんどのゲームは既定でボーダーレスウィンドウモードを使用しており、これは問題なく処理されます) はこの方法でキャプチャできず、常にアプリアイコンにフォールバックします。</p><p>ブラウザデータはブックマークと履歴を個別にインデックス化します — <strong>ブックマークをインデックス化</strong> と <strong>履歴をインデックス化</strong> は <strong>設定 → プラグイン → ブラウザデータ → 設定</strong> の中で別々のトグルになっているため、履歴のインデックス化をオフにしつつ (ブックマークよりもはるかに大きくなりがちです) ブックマークの検索は続けたり、あるいはその逆にしたりできます。</p><h2 id="ウェブ検索" tabindex="-1">ウェブ検索 <a class="header-anchor" href="#ウェブ検索" aria-label="Permalink to &quot;ウェブ検索&quot;">​</a></h2><p>ウェブ検索には、複数のエンジン/サイト向けの既定キーワード — <code>bd</code> (Baidu)、<code>g</code> (Google)、<code>bing</code> (Bing)、<code>gh</code> (GitHub)、<code>wiki</code> (Wikipedia)、<code>yt</code> (YouTube) — が同梱されており、<strong>設定 → プラグイン → ウェブ検索 → 設定</strong> から、それぞれ独自の名前・キーワード・アイコン・URL テンプレートを持つエントリを自由に追加・編集・削除できます。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>g lertaro github</span></span></code></pre></div><p>は、ブラウザで「lertaro github」の Google 検索を開きます。</p><h2 id="翻訳" tabindex="-1">翻訳 <a class="header-anchor" href="#翻訳" aria-label="Permalink to &quot;翻訳&quot;">​</a></h2><p>翻訳プラグインの既定キーワードは <code>tr</code> です。後にテキストを入力すると、Lertaro のインターフェイスで現在選択されている言語へ翻訳します:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>tr hello</span></span></code></pre></div><p>結果は非同期で表示されます。<strong>Enter</strong> を押すかクリックするとコピーできます。翻訳するテキストは Microsoft Translator に送信されるため、インターネット接続が必要です。翻訳先は App の現在の言語設定です。キーワードは <strong>設定 → プラグイン → 翻訳 → 設定</strong> で変更できます。</p><h2 id="ファイルフィルター" tabindex="-1">ファイルフィルター <a class="header-anchor" href="#ファイルフィルター" aria-label="Permalink to &quot;ファイルフィルター&quot;">​</a></h2><p>特定のフォルダーを独自のルールでインデックス化できます。設定はすべて <strong>設定 → プラグイン → ファイルフィルター → 設定</strong> で行います。各ルールには、独自の <strong>対象フォルダー</strong> リスト (再帰的にスキャンされます)、<strong>拡張子/パターン</strong> フィールド (例: <code>*.exe;*.lnk</code> のように、<code>;</code> または <code>,</code> で区切って複数のパターンをすべて一致させることができます。既定の <code>*</code> はすべてのファイルに一致します)、検索結果の説明に表示される任意の <strong>フィルター名</strong> があります。パターンに関わらずサブフォルダーは常に含まれます — パターンによるフィルタリングはファイルのみに適用されます。</p><p>上記の組み込みキーワードと同様に、<strong>ショートカットキーワード</strong> を追加すると、そのルールに一致する結果を通常のインデックスに常に混ぜて表示するのではなく、プレフィックスの背後にゲートできます。</p><h2 id="完全カスタム-キーワードは自分で定義" tabindex="-1">完全カスタム (キーワードは自分で定義) <a class="header-anchor" href="#完全カスタム-キーワードは自分で定義" aria-label="Permalink to &quot;完全カスタム (キーワードは自分で定義)&quot;">​</a></h2><h3 id="カスタムコマンド" tabindex="-1">カスタムコマンド <a class="header-anchor" href="#カスタムコマンド" aria-label="Permalink to &quot;カスタムコマンド&quot;">​</a></h3><p>独自の <code>&lt;キーワード&gt; &lt;引数&gt;</code> コマンドを定義して外部プログラムを起動できます。設定はすべて <strong>設定 → プラグイン → カスタムコマンド → 設定</strong> で行います。コマンドのパラメーターテンプレートは、位置指定のプレースホルダー (スペース区切りの各引数に対応する <code>%s1</code>、<code>%s2</code>、...) と、残り全体を表すプレースホルダー (キーワード以降に入力されたすべてを表す <code>%s</code>) に対応しています。</p><p>各コマンドには <strong>クイックナビゲーションに表示</strong> チェックボックス (既定でオフ) もあります。これをオンにすると、そのコマンドを<a href="./hotkeys.html#クイックナビゲーション-マウス">クイックナビゲーション</a>メニューのルートにも独自の項目として表示し、キーワードをまったく入力せずにクリックできるようにします。<strong>クイックナビゲーションのサブメニュー</strong> フィールドを使うと、ルートの代わりに名前付きのサブメニューにネストできます — <code>/</code> を使うと複数階層ネストできます (2 階層のサブメニューの例: <code>Tools/Network</code>)。空欄のままにすると、コマンドはトップレベルにとどまります。この方法で表示されたコマンドは、設定済みのパラメーターがそのまま使われて実行されます。ここには <code>%s1</code>/<code>%s</code> に代入するための、入力されたテキストが存在しないためです。</p><hr><p>このページのプラグインはいずれも必須ではありません — キーボード操作の余地を奪われたくない場合は、<a href="./settings/plugins.html">設定 → プラグイン</a> からそれぞれ個別に無効化できます。また、<a href="./search-syntax.html">検索構文</a>では、これら以外のすべて (ファイル、フォルダー、アプリケーション) に使われる、常時有効な別のあいまいクエリ言語について説明しています。</p>`,37)])])}const u=t(d,[["render",r]]);export{g as __pageData,u as default};
